      this.speechTimer = setTimeout(() => {
        this.speechTimer = null;
        if (token !== this.speechToken || !this.voiceEnabled()) return;
        try { window.speechSynthesis.speak(utterance); } catch { this.speaking = false; }
      }, 30);
      return true;
    } catch {
      this.speaking = false;
      return false;
    }
  }

  stopSpeaking() {
    this.speechToken++;
    this.speaking = false;
    if (this.speechTimer) { clearTimeout(this.speechTimer); this.speechTimer = null; }
    if (this.ttsSupported) {
      try { window.speechSynthesis.cancel(); } catch {}
    }
  }

  init() {
    this.primeSpeech();
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.enabled ? .18 : 0;
      this.master.connect(this.ctx.destination);
      this.startAmbient();
    } catch { this.ctx = null; }
  }

  setEnabled(on) {
    this.enabled = !!on;
    if (!this.enabled) this.stopSpeaking();
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.linearRampToValueAtTime(this.enabled ? .18 : 0, this.ctx.currentTime + .12);
    }
    if (this.enabled) this.init();
  }

