// GREEN EMPIRE — tiny synthesized sound engine (no external assets).
const TTS_PROFILES = {
  narrator: { pitch: .78, rate: .92, names: ['daniel', 'david', 'google uk english male', 'microsoft david', 'male'] },
  milo: { pitch: .97, rate: .98, names: ['alex', 'daniel', 'guy', 'david', 'male'] },
  dex: { pitch: 1.03, rate: 1.07, names: ['fred', 'alex', 'guy', 'david', 'male'] },
  vera: { pitch: .84, rate: .93, names: ['samantha', 'victoria', 'karen', 'moira', 'aria', 'zira', 'female'] },
  marlow: { pitch: .94, rate: 1.02, names: ['karen', 'moira', 'aria', 'zira', 'samantha', 'female'] },
  lenny: { pitch: 1.06, rate: 1.04, names: ['google uk english male', 'daniel', 'guy', 'david', 'male'] },
  tess: { pitch: .86, rate: .96, names: ['moira', 'tessa', 'zira', 'samantha', 'female'] },
  ward: { pitch: .88, rate: .92, names: ['daniel', 'david', 'google uk english male', 'guy', 'male'] },
  rook: { pitch: .76, rate: .88, names: ['david', 'daniel', 'google uk english male', 'guy', 'male'] },
  nico: { pitch: 1.12, rate: 1.04, names: ['fred', 'alex', 'microsoft guy', 'male'] },
  bea: { pitch: 1.0, rate: 1.0, names: ['aria', 'samantha', 'zira', 'female'] },
  priya: { pitch: 1.08, rate: 1.05, names: ['google us english', 'aria', 'zira', 'samantha', 'female'] }
};

export class Audio {
  constructor(game) {
    this.game = game;
    this.ctx = null;
    this.master = null;
    this.enabled = game?.state?.settings?.sound !== false;
    this.ambientStarted = false;
    this.ttsSupported = typeof window !== 'undefined' && 'speechSynthesis' in window && 'SpeechSynthesisUtterance' in window;
    this.voices = [];
    this.voiceSignature = '';
    this.voiceMap = {};
    this.usedVoices = new Set();
    this.speechToken = 0;
    this.speechTimer = null;
    this.speaking = false;
    this.lastSpeech = null;
    this.speechLog = [];
    if (this.ttsSupported) {
      this.loadVoices();
      try { window.speechSynthesis.onvoiceschanged = () => this.loadVoices(); } catch {}
    }
  }

  loadVoices() {
    if (!this.ttsSupported) return;
    let voices = [];
    try { voices = window.speechSynthesis.getVoices() || []; } catch { voices = []; }
    const signature = voices.map(v => `${v.name || ''}|${v.lang || ''}`).join('~');
    if (signature === this.voiceSignature) return;
    this.voiceSignature = signature;
    this.voices = voices;
    this.voiceMap = {};
    this.usedVoices = new Set();
  }

  primeSpeech() {
    if (!this.ttsSupported) return;
    this.loadVoices();
    try { window.speechSynthesis.resume(); } catch {}
  }

  voiceEnabled() {
    const settings = this.game?.state?.settings;
    return this.ttsSupported && settings?.sound !== false && settings?.voice !== false;
  }

  pickVoice(speakerId) {
    if (this.voiceMap[speakerId] !== undefined) return this.voiceMap[speakerId];
    const english = this.voices.filter(v => /^en([-_]|$)/i.test(v.lang || ''));
    const pool = english.length ? english : this.voices;
    if (!pool.length) return null;
    const profile = TTS_PROFILES[speakerId] || TTS_PROFILES.narrator;
    const scored = pool.map((v, i) => {
      const name = String(v.name || '').toLowerCase();
      let score = 0;
      for (let n = 0; n < profile.names.length; n++) {
        if (name.includes(profile.names[n])) { score = 100 - n * 4; break; }
      }
      if (/^en[-_]us/i.test(v.lang || '')) score += 6;
      else if (/^en[-_]gb/i.test(v.lang || '')) score += 4;
      return { v, score, i };
    }).sort((a, b) => b.score - a.score || a.i - b.i);
    let chosen = scored.find(x => !this.usedVoices.has(x.v.name));
    if (!chosen) chosen = scored[0];
-----UI STORY-----

  startStoryDialogue(m, replay = false) {
    this.storyView = { mode: 'dialogue', mission: m, line: 0, typing: false, typed: 0, text: '', speakerId: '', replay };
    this.setModal(this.storyShell(m), 'story');
    this.renderStoryLine();
  }

  renderStoryLine() {
    const v = this.storyView;
    if (!v) return;
    const line = v.mission.lines[v.line];
    if (!line) { this.afterDialogue(); return; }
    const ch = CHARACTERS[line.s] || CHARACTERS.narrator;
    v.speakerId = line.s;
    $('storyName').textContent = ch.name;
    $('storyRole').textContent = ch.role || '';
    $('storySpeaker').textContent = ch.narrator ? 'THE CITY' : ch.name;
    $('storySpeaker').style.opacity = ch.narrator ? '.65' : '1';
    $('storyText').className = 'story-text' + (ch.narrator ? ' narrator typing' : ' typing');
    $('storyChoices').innerHTML = '';
    $('storyNext').style.visibility = 'visible';
    $('storyNext').innerHTML = `TAP TO CONTINUE ${ico('arrow')}`;
    $('storyDots').innerHTML = v.mission.lines.map((_, i) => `<i class="${i === v.line ? 'on' : ''}"></i>`).join('');
    if (line.s !== v.lastSpeaker) { this.drawPortrait($('storyPortrait'), line.s); v.lastSpeaker = line.s; }
    v.text = line.t; v.typed = 0; v.typing = true;
    $('storyText').textContent = '';
    clearInterval(this.typeTimer);
    this.typeTimer = setInterval(() => {
      if (!this.storyView || this.storyView.mode !== 'dialogue') { clearInterval(this.typeTimer); return; }
      v.typed += 2;
      if (v.typed >= v.text.length) {
        v.typed = v.text.length; v.typing = false;
        $('storyText').textContent = v.text;
        $('storyText').classList.remove('typing');
        clearInterval(this.typeTimer);
      } else {
        $('storyText').textContent = v.text.slice(0, v.typed);
      }
    }, 16);
  }

  advanceStory() {
    const v = this.storyView;
    if (!v) return;
    if (v.mode === 'reply') { this.finishReply(); return; }
    if (v.mode !== 'dialogue') return;
    if (v.typing) {
      v.typing = false;
      clearInterval(this.typeTimer);
      $('storyText').textContent = v.text;
      $('storyText').classList.remove('typing');
      return;
    }
    v.line++;
    if (v.line >= v.mission.lines.length) this.afterDialogue();
    else { this.audio?.click(); this.renderStoryLine(); }
  }

  afterDialogue() {
    const v = this.storyView;
    if (!v) return;
    this.game.markStorySeen();
    if (v.mission.choice) { this.showStoryChoice(v.mission.choice); return; }
    this.showStorySummary(v.mission);
  }

  showStoryChoice(choice) {
    const v = this.storyView;
    if (!v) return;
    v.mode = 'choice';
    $('storyText').textContent = '';
    $('storySpeaker').textContent = 'DECISION';
    $('storyDots').innerHTML = '';
    $('storyNext').style.visibility = 'hidden';
    $('storyChoices').innerHTML = `<div class="choice-prompt">${choice.prompt}</div><div class="story-choice">${choice.options.map((o, i) => `<button class="choice-btn" data-act="storyChoice" data-index="${i}"><b>${o.label}</b><span>${o.sub || ''}</span></button>`).join('')}</div>`;
  }

  applyChoiceEffects(effects = {}) {
    const g = this.game, s = g.state;
    if (effects.dirty) s.dirty = Math.max(0, s.dirty + effects.dirty);
    if (effects.clean) s.clean = Math.max(0, s.clean + effects.clean);
    if (effects.heat) s.heat = clamp(s.heat + effects.heat, 0, 100);
    if (effects.rep) s.rep = clamp(s.rep + effects.rep, 0, 100);
    if (effects.flag) s.flags[effects.flag] = true;
    g.save();
  }

  chooseStory(index) {
    const v = this.storyView;
    if (!v || v.mode !== 'choice') return;
    const choice = v.mission.choice;
    const opt = choice?.options[index];
    if (!opt) return;
    this.applyChoiceEffects(opt.effects);
    this.audio?.click();
    if (opt.effects?.heat) this.toast(`Heat ${opt.effects.heat > 0 ? '+' : ''}${opt.effects.heat}%`, opt.effects.heat > 0 ? 'warn' : 'good');
    v.mode = 'reply';
    v.text = opt.reply || '';
    v.typed = 0; v.typing = true;
    $('storySpeaker').textContent = 'THE CITY';
    $('storySpeaker').style.opacity = '.65';
    $('storyText').className = 'story-text narrator typing';
    $('storyChoices').innerHTML = '';
    $('storyNext').style.visibility = 'visible';
    $('storyNext').innerHTML = `CONTINUE ${ico('arrow')}`;
    clearInterval(this.typeTimer);

